props.onChange:
(
  ($$.newValue) ? 
    (
      /* Look for this number before we try to add it.*/
      $results := $query(
        {
          "statement": "query inventoryNumber($inventoryNumber:String!){\n  inventory(where:{number:{_eq:$inventoryNumber}}) {\n    edges {\n      node {\n        id\n        active\n        createdAt\n        createdByUser {\n          email\n        }\n        updatedAt\n        updatedByUser {\n          email\n        }\n        productStrategyProcess {\n          code\n          productStrategy {\n            code\n            product {\n              code\n            }\n          }\n        }\n        quantity {\n          value\n          unit {\n            code\n          }\n        }\n      }\n    }\n  }\n}",
          "variables": {
            "inventoryNumber": $$.newValue
          }
        }
      );

      ($count($results.inventory.edges)>0) ?
        (
          $addNotificationMessage("Number already used, see message for more details.", {
            "message": "Inventory numbers must be unique.  This one was already used in Fuuz.",
            "severity": "warning",
            "data": $results
          });

          {
            "number": null
          }
        )
        :
        (
          {
            "number": $$.newValue,
            "addMultipleQuantity": 1,
            "addMultiple": false
          }
        )
    )
)

action.mutation:
mutation CreateLotManagement($payload: [LotManagementCreatePayloadInput!]!) {
        mutation: createLotManagement(payload: $payload) { 
          id
          number
      }
    }
